#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn polymulx(c: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == c.len() + 1,
        // First element is exactly 0.0
        result[0] == 0.0f32,
        // Shift/copy property
        forall|i: int| 0 <= i < c.len() ==> result[i + 1] == c[i],
{
    let n: usize = c.len();

    // Start output with a single 0.0
    let mut out: Vec<f32> = Vec::new();
    out.push(0.0f32);

    // Number of elements copied so far from `c`
    let mut i: usize = 0;

    while i < n
        invariant
            0 <= i <= n,
            out.len() == i + 1,
            out[0] == 0.0f32,
            forall|k: int| 0 <= k < i ==> out[k + 1] == c[k],
        decreases (n - i)
    {
        // Copy next element
        out.push(c[i]);

        // After the push, show the shifted property holds for the new element as well.
        // (Existing elements are preserved by push.)
        assert(out[(i as int) + 1] == c[i as int]);

        i = i + 1;
    }

    out
}

} // verus!